style.css:
@-moz-document domain("youtube.com") {
/* Removes standard red buffering lines */
    .ytp-spinner-container {
        border-color: transparent !important;
    }
    
    /* Replaces it with custom colorful rotation */
    .ytp-spinner-rotator {
        border-color: #ff79c6 transparent #f1fa8c transparent !important;
        animation: ytp-spinner-rotate 1s linear infinite !important;
    }
}
